from pathlib import Path
p=Path('backend/src/notes.js');s=p.read_text(encoding='utf-8');s=s.replace("export function registerNotes(app,{col,adminGuard,mutateGuard,requireOrigin,publicOrigin,persistentRateLimit})", "export function registerNotes(app,{col,adminGuard,mutateGuard,requireOrigin,publicOrigin,persistentRateLimit,newsletter})");s=s.replace(" const limit = persistentRateLimit", " const configured=newsletter?.configured || (()=>Boolean(process.env.RESEND_API_KEY?.trim() && process.env.RESEND_FROM?.trim()));\n const subscriptionLimit=persistentRateLimit({name:'subscription-ip',limit:5,windowMs:3600000,message:'Too many subscription requests. Please try again in an hour.'});\n app.get('/api/public/subscription/status',(_req,res)=>res.json({available:configured()}));\n const limit = persistentRateLimit");s=s.replace(' const send = async(to,subject,text)=>{',' const send = newsletter?.send || (async(to,subject,text)=>{');s=s.replace("if(!result.ok) throw new Error(`Resend rejected email (${result.status}).`);\n };", "if(!result.ok) throw new Error(`Resend rejected email (${result.status}).`);\n });")
s=s.replace("app.post('/api/public/subscribe',requireOrigin(publicOrigin),limit", "app.post('/api/public/subscribe',requireOrigin(publicOrigin),subscriptionLimit");s=s.replace("app.post('/api/public/subscription',requireOrigin(publicOrigin),limit", "app.post('/api/public/subscription',requireOrigin(publicOrigin),subscriptionLimit");s=s.replace("if(!process.env.RESEND_API_KEY || !process.env.RESEND_FROM)return res.status(503).json({error:'Subscriptions are not open yet. Please check back soon.'});", "if(!configured())return res.status(503).json({code:'SUBSCRIPTIONS_UNAVAILABLE',error:'Email updates are temporarily unavailable. Please try again later.'});")
s=s.replace("  await send(address,'Confirm your Notes subscription',", "  try { await send(address,'Confirm your Notes subscription',");s=s.replace("Ignore this email if you did not request it.`);", "Ignore this email if you did not request it.`); } catch(error) { console.error('Subscription confirmation failed:',error.message); return res.status(502).json({error:'We could not send your confirmation email. Please try again later.'}); }")
s=s.replace("emailConfigured:!!(process.env.RESEND_API_KEY&&process.env.RESEND_FROM)","emailConfigured:configured()")
