p=Path('src/Notes.jsx');s=p.read_text(encoding='utf-8');s=s.replace(" const root=useRef(null);", " const [subscriptionAvailable,setSubscriptionAvailable]=useState(null);\n useEffect(()=>{request('subscription/status').then(d=>setSubscriptionAvailable(d.available)).catch(()=>setSubscriptionAvailable(false))},[]);\n const root=useRef(null);")
